/**
 * E2E parity workflows for the `toolApproval` WorkflowAgent change.
 * Temporary verification files; never committed.
 *
 * Tool executions are counted with a host-global counter incremented inside a
 * `'use step'` function (steps run in the host realm, the workflow body does
 * not; same technique as test/telemetry-workflows.ts).
 */
import { tool } from 'ai';
import { getWritable } from 'workflow';
import { z } from 'zod/v4';
import { mockSequenceModel } from '../providers/mock.js';
import { WorkflowAgent } from '../workflow-agent.js';

type Scenario = 'user-approval' | 'denied' | 'denied-object' | 'approved';
type Mode = 'stream' | 'generate';

const TOOL_RUNS_KEY = '__E2E_PARITY_TOOL_RUNS';

async function weatherStep(input: { city: string }) {
  'use step';
  const store = ((globalThis as Record<string, any>)[TOOL_RUNS_KEY] ??= {
    count: 0,
  });
  store.count += 1;
  return { city: input.city, temperature: 18 };
}

async function readToolRuns() {
  'use step';
  return ((globalThis as Record<string, any>)[TOOL_RUNS_KEY]?.count ?? 0) as number;
}

const approvals: Record<Scenario, unknown> = {
  'user-approval': { weather: 'user-approval' },
  denied: { weather: 'denied' },
  'denied-object': { weather: { type: 'denied', reason: 'policy' } },
  approved: { weather: 'approved' },
};

function createAgent(scenario: Scenario) {
  return new WorkflowAgent({
    model: mockSequenceModel([
      {
        type: 'tool-call',
        toolName: 'weather',
        input: JSON.stringify({ city: 'London' }),
      },
      { type: 'text', text: 'It is 18C in London.' },
    ]) as any,
    tools: {
      weather: tool({
        description: 'Get the weather for a city',
        inputSchema: z.object({ city: z.string() }),
        execute: weatherStep,
      }),
    },
    // the option does not type-check before the fix; the cast keeps the same
    // file runnable on both trees
    ...({ toolApproval: approvals[scenario] } as any),
  });
}

async function run(scenario: Scenario, mode: Mode) {
  const agent = createAgent(scenario);
  const messages = [
    { role: 'user' as const, content: 'What is the weather in London?' },
  ];
  const result =
    mode === 'generate'
      ? await agent.generate({ messages })
      : await agent.stream({ messages, writable: getWritable() });

  return {
    scenario,
    mode,
    toolRuns: await readToolRuns(),
    modelCalls: result.steps.length,
    step0ContentTypes: result.steps[0]?.content.map(part => part.type),
    toolResultsCount: result.toolResults.length,
    lastStepText: result.steps.at(-1)?.text,
  };
}

export async function toolApprovalParityWorkflow(
  scenario: Scenario,
  mode: Mode,
) {
  'use workflow';
  return await run(scenario, mode);
}
```

