```js
// Part A: provider warnings logged by ToolLoopAgent (reference) and WorkflowAgent.
// Prints only; no assertions. Real @ai-sdk/openai chat provider over HTTP against
// the local mock server. Run from examples/ai-functions.
import { createOpenAI } from '@ai-sdk/openai';
import { WorkflowAgent } from '@ai-sdk/workflow';
import { ToolLoopAgent, tool } from 'ai';
import { createRequire } from 'node:module';
import { z } from 'zod';
import { startMockOpenAI } from '/vercel/sandbox/e2e/mock-openai.mjs';

const require = createRequire(import.meta.url);
console.log('RESOLVE ai                 ', require.resolve('ai'));
console.log('RESOLVE @ai-sdk/workflow   ', require.resolve('@ai-sdk/workflow'));
console.log('RESOLVE @ai-sdk/openai     ', require.resolve('@ai-sdk/openai'));

// Record everything the AI SDK warning logger emits: the default logger uses
// process.emitWarning (falling back to console.warn). Both are recorded and the
// original is still called, so the real stderr output stays visible.
const recorded = [];
const originalEmitWarning = process.emitWarning;
process.emitWarning = function (warning, ...rest) {
  recorded.push(`emitWarning: ${String(warning)}`);
  return originalEmitWarning.call(process, warning, ...rest);
};
const originalConsoleWarn = console.warn;
console.warn = (...args) => {
  recorded.push(`console.warn: ${args.map(String).join(' ')}`);
  originalConsoleWarn(...args);
};

function printRecorded(label) {
  console.log(`  ${label} recorded ${recorded.length} message(s):`);
  for (const message of recorded) console.log(`    | ${message}`);
}

const mock = await startMockOpenAI();
const openai = createOpenAI({ baseURL: mock.baseURL, apiKey: 'test-key' });
const model = openai.chat('gpt-4o-mini');

const tools = {
  weather: tool({
    description: 'Get the weather',
    inputSchema: z.object({ city: z.string() }),
    execute: async ({ city }) => ({ city, temperature: 18 }),
  }),
};

const prompt = 'What is the weather in London?';
// Two-step run: a tool call, then text. `topK` is not supported by the
// OpenAI Chat Completions API, so the provider reports a warning per model call.
const topK = 5;
const script = () => [
  { toolCalls: [{ id: 'call_1', name: 'weather', args: { city: 'London' } }] },
  { text: 'It is 18C in London.' },
];

async function run(label, factory) {
  mock.script(script());
  recorded.length = 0;
  console.log(`\n=== ${label} ===`);
  const result = await factory();
  const steps = await result.steps;
  console.log('  model calls (mock requests):', mock.requests.length);
  console.log('  steps.length:', steps.length);
  console.log('  steps.map(step => step.warnings):', JSON.stringify(steps.map(step => step.warnings)));
  printRecorded(label);
}

await run('ToolLoopAgent.generate (topK: 5)', () =>
  new ToolLoopAgent({ model, tools }).generate({ prompt, topK }),
);

await run('ToolLoopAgent.stream (topK: 5)', async () => {
