// Local mock of the OpenAI Chat Completions API for end-to-end reproductions.
// It lets the real `@ai-sdk/openai` provider run over real HTTP without an API key.
//
//   const mock = await startMockOpenAI();
//   mock.script([{ toolCalls: [{ id: 'call_1', name: 'weather', args: { city: 'London' } }] }, { text: 'It is 18C.' }]);
//   const openai = createOpenAI({ baseURL: mock.baseURL, apiKey: 'test-key' });
//   const model = openai.chat('gpt-4o-mini');
//   ...
//   mock.requests   // parsed JSON bodies of all requests, in order
//   await mock.close();
//
// Each scripted response answers one request, in order. Fields:
//   text       assistant text (optional)
//   toolCalls  [{ id, name, args }] (optional); finish_reason becomes "tool_calls"
//   usage      OpenAI usage object (optional, a default with token details is used)
//   status     HTTP status for an error response (optional), with `error` as the message
//   delayMs    wait before responding (optional)
// Works for both `stream: true` (SSE) and non-streaming requests.
import { createServer } from 'node:http';

export const defaultUsage = {
  prompt_tokens: 10,
  completion_tokens: 20,
  total_tokens: 30,
  prompt_tokens_details: { cached_tokens: 4 },
  completion_tokens_details: { reasoning_tokens: 5 },
};

export async function startMockOpenAI() {
  let queue = [];
  const requests = [];
  const headers = [];

  const server = createServer(async (req, res) => {
    let body = '';
    for await (const chunk of req) body += chunk;
    const request = body ? JSON.parse(body) : {};
    requests.push(request);
    headers.push(req.headers);

    const response = queue.shift() ?? { text: 'UNSCRIPTED RESPONSE' };
    if (response.delayMs) await new Promise(r => setTimeout(r, response.delayMs));

    if (response.status && response.status >= 400) {
      res.writeHead(response.status, { 'content-type': 'application/json' });
      res.end(
        JSON.stringify({
          error: {
            message: response.error ?? 'mock error',
            type: 'invalid_request_error',
            param: null,
            code: null,
          },
        }),
      );
      return;
    }

    const id = `chatcmpl-mock-${requests.length}`;
    const created = 1700000000;
    const model = request.model ?? 'gpt-4o-mini';
    const usage = response.usage ?? defaultUsage;
    const toolCalls = (response.toolCalls ?? []).map((call, index) => ({
      index,
      id: call.id,
      type: 'function',
      function: { name: call.name, arguments: JSON.stringify(call.args ?? {}) },
    }));
    const finishReason = toolCalls.length > 0 ? 'tool_calls' : 'stop';

    if (request.stream) {
      res.writeHead(200, {
        'content-type': 'text/event-stream',
        'cache-control': 'no-cache',
      });
      const send = data => res.write(`data: ${JSON.stringify(data)}\n\n`);
      const chunk = (delta, finish_reason = null) => ({
        id,
        object: 'chat.completion.chunk',
        created,
        model,
        choices: [{ index: 0, delta, finish_reason }],
      });
      send(chunk({ role: 'assistant', content: '' }));
      if (response.text) send(chunk({ content: response.text }));
      if (toolCalls.length > 0) send(chunk({ tool_calls: toolCalls }));
      send(chunk({}, finishReason));
      send({ id, object: 'chat.completion.chunk', created, model, choices: [], usage });
      res.write('data: [DONE]\n\n');
      res.end();
      return;
    }

    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(
      JSON.stringify({
        id,
        object: 'chat.completion',
        created,
        model,
        choices: [
          {
            index: 0,
            message: {
              role: 'assistant',
              content: response.text ?? null,
              ...(toolCalls.length > 0
                ? { tool_calls: toolCalls.map(({ index, ...call }) => call) }
                : {}),
            },
            finish_reason: finishReason,
          },
        ],
        usage,
      }),
    );
  });

  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const { port } = server.address();

  return {
    baseURL: `http://127.0.0.1:${port}/v1`,
    requests,
    headers,
    /** Replace the scripted responses and clear the recorded requests. */
    script(responses) {
      queue = [...responses];
      requests.length = 0;
      headers.length = 0;
    },
    close: () => new Promise(resolve => server.close(resolve)),
  };
}
