// TEMPORARY e2e file (never committed). Model that reports a provider warning on
// every call, serializable so it can cross the workflow step boundary.
import type { SharedV4Warning } from '@ai-sdk/provider';
import {
  WORKFLOW_DESERIALIZE,
  WORKFLOW_SERIALIZE,
} from '@ai-sdk/provider-utils';
import { convertArrayToReadableStream, MockLanguageModelV4 } from 'ai/test';

export type E2EWarningResponse =
  | 'weather-tool'
  | 'completed-work-tool'
  | 'wait-tool'
  | 'text';

type MockStreamResult = Awaited<ReturnType<MockLanguageModelV4['doStream']>>;
type MockStreamPart = MockStreamResult extends {
  stream: ReadableStream<infer PART>;
}
  ? PART
  : never;

const warning: SharedV4Warning = { type: 'unsupported', feature: 'topK' };

const usage = {
  inputTokens: {
    total: 5,
    noCache: 5,
    cacheRead: undefined,
    cacheWrite: undefined,
  },
  outputTokens: { total: 10, text: 10, reasoning: undefined },
};

function toolCallFor(response: E2EWarningResponse, index: number) {
  switch (response) {
    case 'weather-tool':
      return {
        toolName: 'weather',
        input: JSON.stringify({ city: 'London' }),
        toolCallId: `weather-call-${index}`,
      };
    case 'completed-work-tool':
      return {
        toolName: 'completedWork',
        input: '{}',
        toolCallId: `completed-work-call-${index}`,
      };
    case 'wait-tool':
      return {
        toolName: 'waitForInput',
        input: '{}',
        toolCallId: `wait-call-${index}`,
      };
    default:
      throw new Error(`not a tool response: ${response}`);
  }
}

class E2EWarningModel extends MockLanguageModelV4 {
  static [WORKFLOW_SERIALIZE](model: E2EWarningModel) {
    return { responses: model.responses };
  }

  static [WORKFLOW_DESERIALIZE](options: {
    responses: E2EWarningResponse[];
  }) {
    return new E2EWarningModel(options.responses);
  }

  constructor(private readonly responses: E2EWarningResponse[]) {
    const indexFor = (prompt: { role: string }[]) =>
      Math.min(
        prompt.filter(message => message.role === 'assistant').length,
        responses.length - 1,
      );

    super({
      provider: 'e2e-warning-provider',
      modelId: 'e2e-warning-model',
      doGenerate: async options => {
        const index = indexFor(options.prompt);
        const response = responses[index];

        return {
          content:
            response === 'text'
              ? [{ type: 'text' as const, text: 'It is 18C in London.' }]
              : [{ type: 'tool-call' as const, ...toolCallFor(response, index) }],
          finishReason: {
            unified: response === 'text' ? 'stop' : 'tool-calls',
            raw: response === 'text' ? 'stop' : 'tool_calls',
          },
          usage,
          warnings: [warning],
          response: {
            id: `e2e-warning-${index}`,
            modelId: 'e2e-warning-model',
            timestamp: new Date(0),
          },
        };
      },
      doStream: async options => {
        const index = indexFor(options.prompt);
        const response = responses[index];
        const parts: MockStreamPart[] = [
          { type: 'stream-start', warnings: [warning] },
          {
            type: 'response-metadata',
            id: `e2e-warning-${index}`,
            modelId: 'e2e-warning-model',
            timestamp: new Date(0),
          },
        ];

        if (response === 'text') {
          parts.push(
            { type: 'text-start', id: 'text-1' },
            { type: 'text-delta', id: 'text-1', delta: 'It is 18C in London.' },
            { type: 'text-end', id: 'text-1' },
          );
        } else {
          parts.push({ type: 'tool-call', ...toolCallFor(response, index) });
        }

        parts.push({
          type: 'finish',
          finishReason: {
            unified: response === 'text' ? 'stop' : 'tool-calls',
            raw: response === 'text' ? 'stop' : 'tool_calls',
          },
          usage,
        });

        return { stream: convertArrayToReadableStream(parts) };
      },
    });
  }
}

// Constructed outside the workflow module (SWC closure workaround, see
// https://github.com/vercel/workflow/issues/1365).
export function createE2EWarningModel(
  responses: E2EWarningResponse[],
): MockLanguageModelV4 {
  return new E2EWarningModel(responses);
}
