// TEMPORARY e2e file (never committed). Workflows that run WorkflowAgent inside
// the real Workflow runtime with a warning-emitting model and a durable tool step.
import { tool } from 'ai';
import { createHook, getWritable } from 'workflow';
import { z } from 'zod/v4';
import { WorkflowAgent } from '../workflow-agent.js';
import { createE2EWarningModel } from './e2e-warning-model.js';

// Tool step functions ('use step'): these run as durable steps.
async function getWeather(input: { city: string }) {
  'use step';
  return { city: input.city, temperature: 18 };
}

async function completedWork() {
  'use step';
  return 'completed before suspension';
}

const weatherTool = () =>
  tool({
    description: 'Get the weather for a city',
    inputSchema: z.object({ city: z.string() }),
    execute: getWeather,
  });

export async function e2eWarningsGenerate() {
  'use workflow';
  const agent = new WorkflowAgent({
    model: createE2EWarningModel(['weather-tool', 'text']),
    instructions: 'You are a weather assistant.',
    tools: { weather: weatherTool() },
  });
  const result = await agent.generate({ prompt: 'What is the weather in London?' });
  return {
    mode: 'generate',
    text: result.text,
    modelCalls: result.steps.length,
    warningsPerStep: result.steps.map(step => step.warnings.length),
    toolOutputs: result.toolResults.map(toolResult => toolResult.output),
  };
}

export async function e2eWarningsStream() {
  'use workflow';
  const agent = new WorkflowAgent({
    model: createE2EWarningModel(['weather-tool', 'text']),
    instructions: 'You are a weather assistant.',
    tools: { weather: weatherTool() },
  });
  const result = await agent.stream({
    prompt: 'What is the weather in London?',
    writable: getWritable(),
  });
  return {
    mode: 'stream',
    text: result.steps.at(-1)?.text,
    modelCalls: result.steps.length,
    warningsPerStep: result.steps.map(step => step.warnings.length),
    toolOutputs: result.toolResults.map(toolResult => toolResult.output),
  };
}

// Suspends on a hook after two completed model calls, then resumes. The resume
// replays the workflow function, so this shows whether a replay logs the
// warnings of already completed model steps again.
export async function e2eWarningsSuspendResume() {
  'use workflow';
  const agent = new WorkflowAgent({
    model: createE2EWarningModel([
      'completed-work-tool',
      'wait-tool',
      'text',
    ]),
    tools: {
      completedWork: tool({
        inputSchema: z.object({}),
        execute: completedWork,
      }),
      waitForInput: tool({
        inputSchema: z.object({}),
        execute: async () => {
          using hook = createHook<string>();
          return await hook;
        },
      }),
    },
  });
  const result = await agent.generate({ prompt: 'Do work, then wait.' });
  return {
    mode: 'generate-with-resume',
    text: result.text,
    modelCalls: result.steps.length,
    warningsPerStep: result.steps.map(step => step.warnings.length),
  };
}
