export async function e2eWarningsStream() {
  'use workflow';
  const agent = new WorkflowAgent({
    model: createE2EWarningModel(['weather-tool', 'text']),
    instructions: 'You are a weather assistant.',
    tools: { weather: weatherTool() },
  });
