// TEMPORARY e2e file (never committed). Runs WorkflowAgent inside the real
// Workflow runtime and records what the AI SDK warning logger emits.
import { waitForHook } from '@workflow/vitest';
import { describe, expect, it } from 'vitest';
import { resumeHook, start } from 'workflow/api';
import {
  e2eWarningsGenerate,
  e2eWarningsStream,
  e2eWarningsSuspendResume,
} from './test/e2e-parity-workflows.js';

// The AI SDK default warning logger calls process.emitWarning (and falls back to
// console.warn). Record both so the test prints exactly what the logger emitted.
const emitted: string[] = [];
const originalEmitWarning = process.emitWarning;
const originalConsoleWarn = console.warn;

process.emitWarning = function (warning: string | Error, ...rest: unknown[]) {
  emitted.push(`emitWarning: ${String(warning)}`);
  return (originalEmitWarning as (...args: unknown[]) => void).call(
    process,
    warning,
    ...rest,
  );
} as typeof process.emitWarning;

console.warn = (...args: unknown[]) => {
  emitted.push(`console.warn: ${args.map(String).join(' ')}`);
  originalConsoleWarn(...args);
};

// Provider warnings only. The first default-logger call also prints a one-time
// information note ("AI SDK Warning System: ..."), which is counted separately.
function warningMessages(): string[] {
  return emitted.filter(message => message.includes('AI SDK Warning ('));
}

function reset() {
  emitted.length = 0;
}

function summary(label: string, value: Record<string, unknown>) {
  const warnings = warningMessages();
  console.log(
    'E2E-B ' +
      JSON.stringify({
        run: label,
        ...value,
        loggedProviderWarnings: warnings.length,
        loggedProviderWarningText: [...new Set(warnings.map(w => w.slice(w.indexOf('emitWarning: ') + 13)))],
        otherLoggedMessages: emitted.length - warnings.length,
      }),
  );
}

describe('E2E WorkflowAgent provider warnings', { timeout: 120_000 }, () => {
  it('generate(): two model calls, tool as durable step', async () => {
    reset();
    const run = await start(e2eWarningsGenerate, []);
    const value = await run.returnValue;
    expect(value.modelCalls).toBe(2);
    summary('WorkflowAgent.generate', value as Record<string, unknown>);
  });

  it('stream(): two model calls, tool as durable step', async () => {
    reset();
    const run = await start(e2eWarningsStream, []);
    const value = await run.returnValue;
    expect(value.modelCalls).toBe(2);
    summary('WorkflowAgent.stream', value as Record<string, unknown>);
  });

  it('replay after hook resume does not log completed model steps again', async () => {
    reset();
    const run = await start(e2eWarningsSuspendResume, []);
    const hook = await waitForHook(run);
    const beforeResume = warningMessages().length;
    await resumeHook(hook.token, 'resumed input');
    const value = await run.returnValue;
    expect(value.modelCalls).toBe(3);
    summary('WorkflowAgent.generate + hook resume', {
      ...(value as Record<string, unknown>),
      loggedProviderWarningsBeforeResume: beforeResume,
      loggedProviderWarningsAfterResume: warningMessages().length - beforeResume,
    });
  });
});
