// Probes whether globals set by the test process are visible inside a durable
// step, so we know if a warning logged in a step is observable from the test.
async function probeStepGlobals(): Promise<{
  probe: number | null;
  hasWarningsLogger: boolean;
}> {
  'use step';
  return {
    probe: (globalThis as any).__e2eProbe ?? null,
    hasWarningsLogger: typeof (globalThis as any).AI_SDK_LOG_WARNINGS === 'function',
  };
}

export async function agentDefaultStepLimitE2e() {
  'use workflow';
  // Counts how often the workflow body runs, to show that the run replays.
  const bodyRuns = ((globalThis as any).__e2eBodyRuns ?? 0) + 1;
  (globalThis as any).__e2eBodyRuns = bodyRuns;
  console.log('E2E-BODY-RUN ' + bodyRuns);

