import { createRequire } from 'node:module';
import { createOpenAI } from '@ai-sdk/openai';
import { WorkflowAgent } from '@ai-sdk/workflow';
import { isStepCount, ToolLoopAgent, tool } from 'ai';
import { z } from 'zod';
import { startMockOpenAI } from '/vercel/sandbox/e2e/mock-openai.mjs';

const require = createRequire(import.meta.url);
console.log('ai resolved from', require.resolve('ai'));
console.log('@ai-sdk/workflow resolved from', require.resolve('@ai-sdk/workflow'));

// Record AI SDK warnings: log-warnings uses process.emitWarning when available
// and console.warn otherwise. Wrap both before any agent runs.
const recorded = [];
process.emitWarning = (warning, ...rest) => {
  const message =
    typeof warning === 'string'
      ? warning
      : (warning && warning.message) ?? String(warning);
  recorded.push(`process.emitWarning: ${message}`);
};
console.warn = (...args) => {
  recorded.push(
    `console.warn: ${args
      .map(a => (typeof a === 'string' ? a : JSON.stringify(a)))
      .join(' ')}`,
  );
};

const mock = await startMockOpenAI();
const openai = createOpenAI({ baseURL: mock.baseURL, apiKey: 'test-key' });
const model = openai.chat('gpt-4o-mini');

const tools = {
  weather: tool({
    description: 'Get the weather',
    inputSchema: z.object({ city: z.string() }),
    execute: async ({ city }) => ({ city, temperature: 18 }),
  }),
};
const prompt = 'Keep calling the weather tool.';

let callId = 0;
const toolCallStep = () => ({
  toolCalls: [
    { id: `call_${++callId}`, name: 'weather', args: { city: 'London' } },
  ],
});
// At least 25 tool-call responses, so the mock never runs out inside 20 steps.
const alwaysToolCalls = () => Array.from({ length: 25 }, toolCallStep);
const toolCallsThenText = () => [
  ...Array.from({ length: 19 }, toolCallStep),
  { text: 'Done: it is 18C.' },
];

async function run(label, responses, agent) {
  const warningStart = recorded.length;
  mock.script(responses());
  const result = await agent.generate({ prompt });
  const warnings = recorded
    .slice(warningStart)
    .filter(message => message.includes('default stopWhen condition'));
  console.log(
    `[${label}] steps=${result.steps.length} requests=${mock.requests.length} defaultStopWhenWarnings=${warnings.length}`,
  );
  for (const warning of warnings) console.log(`[${label}] ${warning}`);
}

async function runBoth(scenario, responses, options) {
  await run(
    `${scenario} | ToolLoopAgent.generate`,
    responses,
    new ToolLoopAgent({ model, tools, ...options.core }),
  );
  await run(
    `${scenario} | WorkflowAgent.generate`,
    responses,
    new WorkflowAgent({ model, tools, ...options.workflow }),
  );
}

// Scenario 1: no stopWhen, mock always returns a tool call.
await runBoth('scenario 1: no stopWhen', alwaysToolCalls, {
  core: {},
  workflow: {},
});

// Scenario 2: stopWhen: isStepCount(20) set explicitly.
await runBoth('scenario 2: stopWhen=isStepCount(20) explicit', alwaysToolCalls, {
  core: { stopWhen: isStepCount(20) },
  workflow: { stopWhen: isStepCount(20) },
