// Scenario 3: no stopWhen, mock returns 19 tool calls and then text.
await runBoth('scenario 3: 19 tool calls then text', toolCallsThenText, {
  core: {},
  workflow: {},
});

// Scenario 4: no stopWhen, prepareCall returns the settings it received.
await runBoth(
  'scenario 4: prepareCall returns received settings',
  alwaysToolCalls,
  {
    core: { prepareCall: settings => settings },
    workflow: { prepareCall: ({ stopWhen }) => ({ stopWhen }) },
  },
);

await mock.close();
