  const originalConsoleWarn = console.warn;
  process.emitWarning = ((warning: string | Error) => {
    warnings.push(typeof warning === 'string' ? warning : warning.message);
  }) as typeof process.emitWarning;
  console.warn = (...args: unknown[]) => {
    warnings.push(
      args
        .map(a => (typeof a === 'string' ? a : JSON.stringify(a)))
        .join(' '),
    );
  };

  (globalThis as any).__e2eBodyRuns = 0;
  (globalThis as any).__e2eProbe = 42;

  try {
    const run = await start(agentDefaultStepLimitE2e);
    const value = await run.returnValue;
    const status = await run.status;

    const defaultLimitWarnings = warnings.filter(message =>
      message.includes('default stopWhen condition'),
    );

    console.log(
      'E2E-B ' +
        JSON.stringify({
          stepCount: value.stepCount,
          workflowBodyRuns: value.bodyRuns,
          stepGlobals: value.stepGlobals,
          status,
          recordedWarnings: warnings.length,
          defaultStopWhenWarningCount: defaultLimitWarnings.length,
          defaultStopWhenWarnings: defaultLimitWarnings,
          allRecordedWarnings: warnings,
        }),
    );

    expect(value.stepCount).toBe(20);
  } finally {
    process.emitWarning = originalEmitWarning;
    console.warn = originalConsoleWarn;
  }
});
