/**
 * Temporary workflow for the one-off experimental_refineToolInput e2e check
 * (never committed). Runs WorkflowAgent inside a real Workflow runtime with a
 * tool whose `execute` is a durable step that returns the input it received.
 */
import { tool } from 'ai';
import { getWritable } from 'workflow';
import { z } from 'zod/v4';
import { WorkflowAgent } from '../workflow-agent.js';
import { mockSequenceModel } from '../providers/mock.js';
import { refineWeatherInputToParis } from './e2e-parity-refine.js';

async function weatherStep(input: { city: string }): Promise<{ city: string }> {
  'use step';
  // Return the input the tool actually received.
  return input;
}

const script = [
  {
    type: 'tool-call' as const,
    toolName: 'weather',
    input: JSON.stringify({ city: 'London' }),
  },
  { type: 'text' as const, text: 'It is 18C in Paris.' },
];

const prompt = 'What is the weather in London?';

function createAgent() {
  return new WorkflowAgent({
    model: mockSequenceModel([...script]),
    tools: {
      weather: tool({
        description: 'Get the weather',
        inputSchema: z.object({ city: z.string() }),
        execute: weatherStep,
      }),
    },
    experimental_refineToolInput: { weather: refineWeatherInputToParis } as any,
  });
}

function describe(result: any) {
  return {
    stepCount: result.steps.length,
    executedInput: result.steps[0]?.toolResults?.[0]?.output,
    stepToolCallInput: result.steps[0]?.toolCalls?.[0]?.input,
    stepToolResultInput: result.steps[0]?.toolResults?.[0]?.input,
    lastStepText: result.steps.at(-1)?.text,
  };
}

export async function e2eParityRefineGenerate() {
  'use workflow';
  const agent = createAgent();
  const result = await agent.generate({
    messages: [{ role: 'user', content: prompt }],
  });
  return describe(result);
}

export async function e2eParityRefineStream() {
  'use workflow';
  const agent = createAgent();
  const result = await agent.stream({
    messages: [{ role: 'user', content: prompt }],
    writable: getWritable(),
  });
  return describe(result);
}
```

