// Part A reproduction: experimental_refineToolInput in ToolLoopAgent vs WorkflowAgent.
// Run from examples/ai-functions so the workspace packages resolve:
//   cd /vercel/sandbox/base/examples/ai-functions && node --input-type=module < /vercel/sandbox/e2e/repro.mjs
import { createOpenAI } from '@ai-sdk/openai';
import { WorkflowAgent } from '@ai-sdk/workflow';
import { ToolLoopAgent, jsonSchema, tool } from 'ai';
import { createRequire } from 'node:module';
import { z } from 'zod';
import { startMockOpenAI } from '/vercel/sandbox/e2e/mock-openai.mjs';

const require = createRequire(import.meta.url);
console.log('ai resolved from', require.resolve('ai'));
console.log('@ai-sdk/workflow resolved from', require.resolve('@ai-sdk/workflow'));

// Capture AI SDK warnings (both console.warn and process.emitWarning).
const warnings = [];
console.warn = (...args) => {
  warnings.push(args.map(String).join(' '));
};
const originalEmitWarning = process.emitWarning.bind(process);
process.emitWarning = (warning, ...rest) => {
  warnings.push(
    typeof warning === 'string' ? warning : (warning?.message ?? String(warning)),
  );
  return originalEmitWarning(warning, ...rest);
};

const j = value =>
  JSON.stringify(value, (_key, val) =>
    val === undefined ? '<undefined>' : val,
  );

const mock = await startMockOpenAI();
const model = createOpenAI({
  baseURL: mock.baseURL,
  apiKey: 'test-key',
}).chat('gpt-4o-mini');
const prompt = 'What is the weather in London?';

// The refinement function is a plain function in both cases.
const refineToParis = input => ({ ...input, city: 'Paris' });

const zodTools = seen => ({
  weather: tool({
    description: 'Get the weather',
    inputSchema: z.object({ city: z.string() }),
    execute: async input => {
      seen.push(input);
      return { temperature: 18 };
    },
  }),
});

// jsonSchema without a `validate` function has no runtime validator.
const schemaOnlyTools = seen => ({
  weather: tool({
    description: 'Get the weather',
    inputSchema: jsonSchema({
      type: 'object',
      properties: { city: { type: 'string' } },
      required: ['city'],
    }),
    execute: async input => {
      seen.push(input);
      return { temperature: 18 };
    },
  }),
});

const approvalTools = seen => ({
  weather: tool({
    description: 'Get the weather',
    inputSchema: z.object({ city: z.string() }),
    needsApproval: true,
    execute: async input => {
      seen.push(input);
      return { temperature: 18 };
    },
  }),
});

// Two steps: a `weather` tool call with { city: 'London' }, then text.
const toolCallScript = () => [
  { toolCalls: [{ id: 'call_1', name: 'weather', args: { city: 'London' } }] },
  { text: 'It is 18C in London.' },
];

function assistantToolCalls(request) {
  if (!request) return '<second request missing>';
  const calls = [];
  for (const message of request.messages ?? []) {
    if (message.role !== 'assistant') continue;
    for (const call of message.tool_calls ?? []) {
      calls.push({
        name: call.function?.name,
        arguments: call.function?.arguments,
      });
    }
  }
  return calls;
}

async function run(label, AgentClass, mode, makeTools, placement = 'constructor') {
  const seen = [];
  const tools = makeTools(seen);
  mock.script(toolCallScript());
  const agent = new AgentClass({
    model,
    tools,
    ...(placement === 'constructor'
      ? { experimental_refineToolInput: { weather: refineToParis } }
      : {}),
  });
  const callOptions = {
    prompt,
    ...(placement === 'call'
      ? { experimental_refineToolInput: { weather: refineToParis } }
      : {}),
  };

  let result;
  if (mode === 'generate') {
    result = await agent.generate(callOptions);
  } else {
    result = await agent.stream(callOptions);
    if (typeof result.consumeStream === 'function') {
      await result.consumeStream();
    }
  }
  const steps = Array.isArray(result.steps) ? result.steps : await result.steps;

  console.log(
    label + ' | requests=' + mock.requests.length + ' steps=' + steps.length,
  );
  console.log(label + ' | execute.receivedInputs ' + j(seen));
  console.log(
    label + ' | steps[0].toolCalls[0].input ' + j(steps[0]?.toolCalls?.[0]?.input),
  );
  console.log(
    label +
      ' | steps[0].toolResults[0].input ' +
      j(steps[0]?.toolResults?.[0]?.input),
  );
  console.log(
    label +
      ' | requests[1].assistantToolCalls ' +
      j(assistantToolCalls(mock.requests[1])),
  );
}

const agents = [
  [ToolLoopAgent, 'ToolLoopAgent'],
  [WorkflowAgent, 'WorkflowAgent'],
];

for (const [scenarioLabel, makeTools] of [
  ['zod schema', zodTools],
  ['jsonSchema without validate', schemaOnlyTools],
]) {
  console.log('');
  console.log(
    '### Scenario: ' +
      scenarioLabel +
      ", experimental_refineToolInput: { weather: input => ({ ...input, city: 'Paris' }) } in the constructor",
  );
  for (const mode of ['generate', 'stream']) {
    for (const [AgentClass, agentLabel] of agents) {
      await run('[' + agentLabel + '.' + mode + '][' + scenarioLabel + ']', AgentClass, mode, makeTools);
    }
  }
}

console.log('');
console.log('### Per-call experimental_refineToolInput (not the constructor)');
for (const [AgentClass, agentLabel] of agents) {
  await run(
    '[' + agentLabel + '.generate][zod schema][per-call option]',
    AgentClass,
    'generate',
    zodTools,
    'call',
  );
}

function approvalRequestsOf(messages) {
  const requests = [];
  for (const message of messages ?? []) {
    if (message.role !== 'assistant') continue;
    for (const part of message.content ?? []) {
      if (part.type === 'tool-approval-request') {
        requests.push({ approvalId: part.approvalId, toolCallId: part.toolCallId });
      }
    }
  }
  return requests;
}

// WorkflowAgent only: approval tool, first call stops, second call approves.
for (const mode of ['generate', 'stream']) {
  console.log('');
  console.log(
    '### WorkflowAgent.' + mode + ': zod tool with needsApproval: true (two calls)',
  );
  const seen = [];
  mock.script([
    { toolCalls: [{ id: 'call_1', name: 'weather', args: { city: 'London' } }] },
  ]);
  const agent = new WorkflowAgent({
    model,
    tools: approvalTools(seen),
    experimental_refineToolInput: { weather: refineToParis },
  });

  let first;
  let firstSteps;
  if (mode === 'generate') {
    first = await agent.generate({
      messages: [{ role: 'user', content: prompt }],
    });
    firstSteps = first.steps;
  } else {
    first = await agent.stream({
      messages: [{ role: 'user', content: prompt }],
    });
    firstSteps = first.steps;
  }
  const firstResponseMessages =
    mode === 'generate'
      ? first.responseMessages
      : firstSteps.flatMap(step => step.response.messages);
