```ts
/**
 * Custom model for the one-off async generator tool parity check (temporary
 * file, never committed). Modelled on ./mock-function-wrapper.ts so it works
 * inside a durable workflow step.
 *
 * `node:fs` is not available in workflow code, so model calls are counted in
 * module state inside the model and the call number is appended to the text of
 * the text response. The last step text therefore shows how many model calls
 * the run made.
 */
import {
  WORKFLOW_DESERIALIZE,
  WORKFLOW_SERIALIZE,
} from '@ai-sdk/provider-utils';
import { convertArrayToReadableStream, MockLanguageModelV4 } from 'ai/test';

type Descriptor =
  | { type: 'text'; text: string }
  | { type: 'tool-call'; toolName: string; input: string };

type StreamPart = Awaited<
  ReturnType<MockLanguageModelV4['doStream']>
>['stream'] extends ReadableStream<infer PART>
  ? PART
  : never;

const usage = {
  inputTokens: {
    total: 5,
    noCache: 5,
    cacheRead: undefined,
    cacheWrite: undefined,
  },
  outputTokens: { total: 10, text: 10, reasoning: undefined },
};

let modelCallCount = 0;

/** Counts model calls of one run, reset by the first call of a run. */
function recordCall(prompt: { role: string }[]) {
  if (!prompt.some(message => message.role === 'assistant')) {
    modelCallCount = 0;
  }
  modelCallCount += 1;
  return modelCallCount;
}

class GeneratorToolModel extends MockLanguageModelV4 {
  static [WORKFLOW_SERIALIZE](model: GeneratorToolModel) {
    return { responses: model.responses };
  }

  static [WORKFLOW_DESERIALIZE](options: { responses: Descriptor[] }) {
    return new GeneratorToolModel(options.responses);
  }

  constructor(private readonly responses: Descriptor[]) {
    super({
      provider: 'e2e-parity-test',
      modelId: 'e2e-parity-generator-model',
      doGenerate: async options => {
        const call = recordCall(options.prompt);
        const index = Math.min(
          options.prompt.filter(message => message.role === 'assistant')
            .length,
          responses.length - 1,
        );
        const response = responses[index]!;
        return {
          content:
            response.type === 'text'
              ? [{ type: 'text', text: `${response.text} [model call ${call}]` }]
              : [
                  {
                    type: 'tool-call',
                    toolCallId: `call-${index + 1}`,
                    toolName: response.toolName,
                    input: response.input,
                  },
                ],
          finishReason: {
            unified: response.type === 'text' ? 'stop' : 'tool-calls',
            raw: undefined,
          },
          usage,
          warnings: [],
          response: {
            id: 'e2e-parity-response',
            modelId: 'e2e-parity-generator-model',
            timestamp: new Date(),
          },
        };
      },
      doStream: async options => {
        const call = recordCall(options.prompt);
        const index = Math.min(
          options.prompt.filter(message => message.role === 'assistant')
            .length,
          responses.length - 1,
        );
        const response = responses[index]!;
        const prefix: StreamPart[] = [
          { type: 'stream-start', warnings: [] },
          {
            type: 'response-metadata',
            id: 'e2e-parity-response',
            modelId: 'e2e-parity-generator-model',
            timestamp: new Date(),
          },
        ];
        const parts: StreamPart[] =
          response.type === 'text'
            ? [
                ...prefix,
                { type: 'text-start', id: '1' },
                {
                  type: 'text-delta',
                  id: '1',
                  delta: `${response.text} [model call ${call}]`,
                },
                { type: 'text-end', id: '1' },
                {
                  type: 'finish',
                  finishReason: { unified: 'stop', raw: 'stop' },
                  usage,
                },
              ]
            : [
                ...prefix,
                {
                  type: 'tool-call',
                  toolCallId: `call-${index + 1}`,
                  toolName: response.toolName,
                  input: response.input,
                },
                {
                  type: 'finish',
                  finishReason: { unified: 'tool-calls', raw: 'tool-calls' },
                  usage,
                },
              ];
        return { stream: convertArrayToReadableStream(parts) };
      },
    });
  }
}

// Keep construction outside workflow modules for the SWC closure transform.
export function generatorToolModel() {
  return new GeneratorToolModel([
    {
      type: 'tool-call',
      toolName: 'weather',
      input: '{"city":"London"}',
    },
    { type: 'text', text: 'It is 18C in London.' },
  ]);
}
