  JSON.stringify(value, (_key, val) =>
    val === undefined ? '<undefined>' : val,
  );

function modelCalls(value: { lastStepText?: string }) {
  const match = /\[model call (\d+)\]/.exec(value.lastStepText ?? '');
  return match ? Number(match[1]) : null;
}

async function runWorkflow(label: string, workflow: any) {
