          step0ToolOutputs: value.step0ToolOutputs,
          lastStepText: value.lastStepText,
          stepCount: value.stepCount,
          modelCalls: modelCalls(value),
        }),
    );
  } catch (error: any) {
    const message = String(error?.message ?? error).split('\n')[0];
    console.log(`E2E-B ${label} ERROR: ${message}`);
  }
}

