/**
 * Temporary workflows for the one-off async generator tool parity check (never
 * committed). Runs WorkflowAgent inside a real Workflow runtime with a tool
 * whose `execute` is an async generator, and returns plain serializable data.
 */
import { tool } from 'ai';
import { z } from 'zod/v4';
import { getWritable } from 'workflow';
import { WorkflowAgent } from '../workflow-agent.js';
import { generatorToolModel } from './e2e-parity-model.js';

async function lookupTemperature(city: string): Promise<number> {
  'use step';
  return city === 'London' ? 18 : 21;
}

function plainGeneratorTools() {
  return {
    weather: tool({
      description: 'Get the weather for a city',
      inputSchema: z.object({ city: z.string() }),
      execute: async function* ({ city }: { city: string }) {
        yield { status: 'loading', city };
        yield { temperature: 18, city };
      },
    }),
  };
}

function durableGeneratorTools() {
  return {
    weather: tool({
      description: 'Get the weather for a city',
      inputSchema: z.object({ city: z.string() }),
      execute: async function* ({ city }: { city: string }) {
        yield { status: 'loading', city };
        const temperature = await lookupTemperature(city);
        yield { temperature, city };
      },
    }),
  };
}

/**
 * The return value of a workflow must be serializable, so describe each tool
 * output instead of returning it: before the fix the output is a generator
 * object, which cannot be serialized.
 */
function describeOutput(output: any) {
  let json: string;
  try {
    json = JSON.stringify(output) ?? String(output);
  } catch (error) {
    json = `unserializable: ${String(error)}`;
  }
  return {
    json,
    isAsyncIterable:
      output != null && typeof output[Symbol.asyncIterator] === 'function',
    tag: Object.prototype.toString.call(output),
  };
}

function summarize(result: any) {
  return {
    stepCount: result.steps.length,
    step0ToolOutputs: result.steps[0]?.toolResults?.map((toolResult: any) =>
      describeOutput(toolResult.output),
    ),
    lastStepText: result.steps.at(-1)?.text,
  };
}

export async function e2eGeneratorToolGenerate() {
  'use workflow';
  const agent = new WorkflowAgent({
    model: generatorToolModel(),
    tools: plainGeneratorTools(),
  });
  const result = await agent.generate({
    prompt: 'What is the weather in London?',
  });
  return summarize(result);
}

export async function e2eGeneratorToolStream() {
  'use workflow';
  const agent = new WorkflowAgent({
    model: generatorToolModel(),
    tools: plainGeneratorTools(),
  });
  const result = await agent.stream({
    prompt: 'What is the weather in London?',
    writable: getWritable(),
  });
  return summarize(result);
}

export async function e2eGeneratorToolStepGenerate() {
  'use workflow';
  const agent = new WorkflowAgent({
    model: generatorToolModel(),
    tools: durableGeneratorTools(),
  });
  const result = await agent.generate({
    prompt: 'What is the weather in London?',
  });
  return summarize(result);
}

export async function e2eGeneratorToolStepStream() {
  'use workflow';
  const agent = new WorkflowAgent({
    model: generatorToolModel(),
    tools: durableGeneratorTools(),
  });
  const result = await agent.stream({
    prompt: 'What is the weather in London?',
    writable: getWritable(),
  });
  return summarize(result);
}
