/**
 * One-off end-to-end check: WorkflowAgent in a real Workflow runtime with an
 * async generator tool. Temporary file, never committed.
 *
 * Model calls are counted inside the mock model (module state, because
 * `node:fs` is not available in workflow code). The text response carries the
 * call number, so the last step text shows how many model calls the run made.
 */
import { describe, expect, it } from 'vitest';
import { start } from 'workflow/api';

import {
  e2eGeneratorToolGenerate,
  e2eGeneratorToolStepGenerate,
  e2eGeneratorToolStepStream,
  e2eGeneratorToolStream,
} from './test/e2e-parity-workflows.js';

const j = (value: unknown) =>
  JSON.stringify(value, (_key, val) =>
    val === undefined ? '<undefined>' : val,
  );

function modelCalls(value: { lastStepText?: string }) {
  const match = /\[model call (\d+)\]/.exec(value.lastStepText ?? '');
  return match ? Number(match[1]) : null;
}

async function runWorkflow(label: string, workflow: any) {
  try {
    const run = await start(workflow, []);
    const value: any = await run.returnValue;
    console.log(
      `E2E-B ${label} ` +
        j({
          step0ToolOutputs: value.step0ToolOutputs,
          lastStepText: value.lastStepText,
          stepCount: value.stepCount,
          modelCalls: modelCalls(value),
        }),
    );
  } catch (error: any) {
    const message = String(error?.message ?? error).split('\n')[0];
    console.log(`E2E-B ${label} ERROR: ${message}`);
  }
}

describe('e2e parity: WorkflowAgent async generator tools', { timeout: 180_000 }, () => {
  it('generate() uses the last yielded value in a real workflow', async () => {
    await runWorkflow('generate', e2eGeneratorToolGenerate);
    expect(true).toBe(true);
  });

  it('stream() uses the last yielded value in a real workflow', async () => {
    await runWorkflow('stream', e2eGeneratorToolStream);
    expect(true).toBe(true);
  });

  it('generate() works when the generator calls a step function', async () => {
    await runWorkflow('generate-with-step', e2eGeneratorToolStepGenerate);
    expect(true).toBe(true);
  });

  it('stream() works when the generator calls a step function', async () => {
    await runWorkflow('stream-with-step', e2eGeneratorToolStepStream);
    expect(true).toBe(true);
  });
});
